const UNITS=[['px','픽셀'],['pct','퍼센트'],['in','인치'],['cm','센티미터'],['mm','밀리미터'],['pt','포인트']];
function toPx(v,u,dpi,base){v=+v||0;switch(u){case'pct':return base*v/100;case'in':return v*dpi;case'cm':return v/2.54*dpi;case'mm':return v/25.4*dpi;case'pt':return v/72*dpi;default:return v}}
function fromPx(px,u,dpi,base){let r;switch(u){case'pct':r=px/base*100;break;case'in':r=px/dpi;break;case'cm':r=px/dpi*2.54;break;case'mm':r=px/dpi*25.4;break;case'pt':r=px/dpi*72;break;default:return Math.round(px)}return Math.round(r*100)/100}
const MB=(w,hh)=>(w*hh*3/1048576).toFixed(1)+'M';

